"""Read-only synthesis of frozen synthetic benchmark receipts; no cipher search."""
import hashlib,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]

def summary(directory=None):
    directory=Path(directory) if directory else ROOT/'results/sigaba-joint-toy';records=[];hashes={}
    for i in range(13):
        p=directory/f'case-{i:02d}.json'
        if not p.is_file():raise ValueError('Benchmark still pending: '+p.name)
        raw=p.read_bytes();r=json.loads(raw);hashes[str(p.relative_to(ROOT)) if ROOT in p.parents else p.name]=hashlib.sha256(raw).hexdigest();s=r.get('solver',{})
        records.append(dict(case=i,q=r.get('fixture',{}).get('q'),rotors=r.get('fixture',{}).get('r'),mask=r.get('fixture',{}).get('mask'),inference_completed=s.get('completed',False),verification_completed=r.get('verification_completed',False),independent_complete_truth_requested=r.get('independent_truth_requested'),full_sets_byte_equal=r.get('full_sets_byte_equal'),exact_raw_key_count=s.get('exact_raw_key_count'),found_raw_keys_lower_bound=s.get('found_raw_keys_lower_bound'),raw_key_descriptions=s.get('raw_key_descriptions'),complete_prefix_raw_descriptions=s.get('complete_prefix_raw_descriptions'),controller_starts_completed=s.get('control_starts_completed'),controller_starts_requested=s.get('control_starts_requested'),index_classes=s.get('reachable_index_classes'),branches=s.get('branches_visited'),max_live_branches=s.get('max_live_branches'),predicate_builds=s.get('predicate_builds'),cache_hits=s.get('predicate_cache_hits'),cache_evictions=s.get('predicate_cache_evictions'),peak_RSS_bytes=r.get('benchmark_budget',{}).get('peak_RSS_bytes'),seconds=r.get('benchmark_budget',{}).get('seconds',r.get('seconds')),reason=r.get('verification_reason') or s.get('reason') or r.get('status'),planted_key_retained=r.get('planted_key_retained'),returned_raw_keys_independently_checked=r.get('returned_raw_keys_independently_checked')))
    real_dimensions=dict(alphabet=26,cipher_rotors=5,control_rotors=5,index_rotors=5,index_alphabet=10,known_reachable_index_classes=66058,cipher_start_bitset_payload_bytes=(26**5+7)//8,control_start_tuples=26**5)
    return dict(id='SIGABA-JOINT-TOY-012',scope='Complete coupled synthetic machines, not actual K4 or full-sized historical-machine inference',K4_evaluations=0,independent_complete_set_comparisons_passed=sum(r['full_sets_byte_equal'] is True for r in records),inference_completed_cases=sum(r['inference_completed'] for r in records),all_declared_scaling_verifications_passed=all(r['inference_completed'] and r['verification_completed'] for r in records[10:]),real_sized_gate_passed=False,real_dimensions=real_dimensions,records=records,receipt_sha256=hashes,limitations=['Control starts are still exhaustively enumerated; they are not symbolic solver variables.','A shared index-map domain is propagated; independent per-time masks are never substituted.','Small q<=4 cases excite every contact, so control-start ambiguity is structural and expected.','Toy index banks have two rotors; real five-index reachable mappings and 26-symbol contacts are not implemented by this model.','Raw keys and raw description coverage are not distinct schedules, plaintexts or independent decryptions.','Measured RSS guards are not an OS hard allocator; watchdog and partial outcomes are reported explicitly.','The 64 MiB cache budget is accounted payload/entry estimation, not all interpreter RSS.','No actual K4 ciphertext is loaded, no packages installed and no real-key slice is substituted for a scaling gate.'])
if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args();Path(a.output).write_text(json.dumps(summary(),indent=2)+'\n')
